values.headerSass:
.custom-header {
.first-tier {
    height: 80px;
    margin-bottom: 0px;
  }

  .first-tier .nav>li>a {
    margin-top: 20px;
    padding: 3px 6px;
  }

  .first-tier .nav>li>a:focus,
  .first-tier .nav>li>a:hover {
    background-color: #002A55;
    color: #fff;
  }

  .first-tier .site-logo img {
    vertical-align: middle;
  }

  .first-tier h2 {
    display: inline;
    font-size: 20px;
  }

  .second-tier {
    height: 40px;
    margin-bottom: 0px;
  }

    .second-tier .nav>li>a {
      margin-top: 10px;
      padding: 3px 6px;
    } 

    .second-tier .nav>li>a:focus,
    .second-tier .nav>li>a:hover {
      background-color: #001A36;
      color: #fff;
    }

    .second-tier .site-subheader img {
      vertical-align: middle;
    }

    .second-tier h2 {
      display: inline;
      font-size: 20px;
    }

}

values.footerSass:
.custom-footer {
  .footer-break {
  padding-top:25px;
