}

.footer-background {
    padding-top: 20px;
    padding-bottom: 20px;
    background-color: #e1e1e1;

  }

  .logo, .nav {
    margin-bottom: 10px;

  }
.footer-base {
    padding-top: 5px;
    padding-bottom: 10px;

  }
  .nav-color {
    color: #001a36;
      }


  .nav-pills {
      display: flex;
      justify-content: center;

  }

  }
